<?php
namespace Tests\Feature;
use App\Models\{User,TrainingSession,AttendanceMark,TrainingTopic,Qualification,LearningTask};
use App\Support\{CentreManagerAccess as A,CentreOversight as O};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\DB;
use Tests\Support\CentreManagerFixture;
use Tests\TestCase;
class CentreOversightTest extends TestCase {
 use LazilyRefreshDatabase,CentreManagerFixture;
 public function test_group_scope_filters_before_search_and_pagination():void {$f=$this->f();$this->granted($f);$this->actingAs($f['manager'])->get('/centre-oversight')->assertOk()->assertSee('PRIVATE-APPRENTICE49')->assertDontSee('PRIVATE-OUTSIDE49')->assertHeader('Referrer-Policy','no-referrer');$this->get('/centre-oversight?search=PRIVATE-OUTSIDE49')->assertOk()->assertDontSee('PRIVATE-OUTSIDE49</h3>',false);$this->assertSame(1,A::people($f['manager'])->count());}
 public function test_only_granted_area_and_current_group_records_can_open():void {$f=$this->f();$this->granted($f);$this->actingAs($f['manager'])->get('/centre-oversight/apprentices/'.$f['a']->id.'/training')->assertOk();$this->get('/centre-oversight/apprentices/'.$f['outside']->id.'/training')->assertForbidden();$this->get('/centre-oversight/apprentices/'.$f['a']->id.'/reviews')->assertForbidden();}
 public function test_training_status_excludes_answers_and_private_support_context():void {$f=$this->f();$this->granted($f);$p=O::position($f['manager'],$f['a'],'training',$f['from'],$f['to']);$this->assertSame(1,$p['data']['overdue_work']);$this->assertArrayHasKey('task_deadline',$p['flags']);foreach(['PRIVATE-ANSWER49','PRIVATE-SUPPORT49','PRIVATE-OUTCOME49','ehcp']as$secret){$this->assertStringNotContainsString($secret,json_encode($p));}}
 public function test_pending_task_source_is_not_counted_as_known_approved_task():void {$f=$this->f();$this->granted($f);LearningTask::factory()->create(['apprentice_id'=>$f['a']->id,'status'=>'Approved','reference'=>'PENDING-49','template'=>['kind'=>'source-pending']]);$p=O::position($f['manager'],$f['a'],'training',$f['from'],$f['to']);$this->assertSame(0,$p['data']['approved']);$this->assertSame(1,$p['data']['source_pending']);$this->assertArrayHasKey('training_source',$p['flags']);}
 public function test_review_history_without_a_checked_copy_stays_unknown_not_overdue():void {$f=$this->f();$this->granted($f,['reviews','coordination']);$p=O::position($f['manager'],$f['a'],'reviews',$f['from'],$f['to']);$this->assertNull($p['data']['cycle']['next_due']);$this->assertArrayHasKey('review_history',$p['flags']);$this->assertArrayNotHasKey('review_due',$p['flags']);$this->assertStringNotContainsString('PRIVATE-OUTCOME49',json_encode($p));}
 public function test_attendance_unknown_sources_do_not_become_zero_or_complete_percentages():void {$f=$this->f();$this->granted($f,['attendance','coordination']);TrainingSession::factory()->create(['tutor_group_id'=>$f['group']->id,'created_by'=>$f['admin']->id,'session_date'=>today()->subDays(10),'start_time'=>'09:00','end_time'=>'10:00','members'=>[$f['a']->id]]);$p=O::position($f['manager'],$f['a'],'attendance',$f['from'],$f['to']);$this->assertNull($p['data']['attendance']['percent']);$this->assertSame(1,$p['data']['attendance']['unmarked']);$this->assertArrayHasKey('attendance_source',$p['flags']);}
 public function test_corrupt_roster_in_selected_source_withholds_attendance_summary():void {$f=$this->f();$this->granted($f,['attendance']);TrainingSession::factory()->create(['tutor_group_id'=>$f['group']->id,'created_by'=>$f['admin']->id,'session_date'=>today()->subDays(10),'members'=>[$f['a']->id,$f['a']->id]]);$p=O::position($f['manager'],$f['a'],'attendance',$f['from'],$f['to']);$this->assertNull($p['data']['attendance']);$this->assertArrayHasKey('attendance_source',$p['flags']);}
 public function test_maths_topics_do_not_award_a_qualification_or_add_main_aim_otj():void {$f=$this->f();$this->granted($f,['functional_skills']);TrainingTopic::factory()->create(['apprentice_id'=>$f['a']->id,'subject'=>'maths','status'=>'Completed','planned_hours'=>3]);$p=O::position($f['manager'],$f['a'],'functional_skills',$f['from'],$f['to']);$this->assertSame(1,$p['data']['maths']['completed_topics']);$this->assertSame([],$p['data']['maths']['qualifications']);$this->assertArrayNotHasKey('recorded_minutes',$p['data']['maths']);}
 public function test_maths_only_owner_cannot_read_english_status_through_followup_view():void {$f=$this->f();$maths=User::factory()->create(['role'=>'functional_skills_tutor','subject_scope'=>'maths']);$f['a']->update(['maths_tutor_id'=>$maths->id]);$p=O::position($maths,$f['a'],'functional_skills',$f['from'],$f['to']);$this->assertArrayHasKey('maths',$p['data']);$this->assertArrayNotHasKey('english',$p['data']);}
 public function test_fresh_source_fingerprint_changes_when_task_status_changes():void {$f=$this->f();$this->granted($f);$p=O::position($f['manager'],$f['a'],'training',$f['from'],$f['to']);$f['task']->forceFill(['status'=>'Approved','version'=>2])->save();$q=O::position($f['manager'],$f['a'],'training',$f['from'],$f['to']);$this->assertNotSame($p['source_hash'],$q['source_hash']);$this->assertArrayNotHasKey('task_deadline',$q['flags']);}
 public function test_opening_overview_and_sections_has_no_work_or_audit_writes():void {$f=$this->f();$this->granted($f);$before=DB::table('portal_operations_events')->count();$this->actingAs($f['manager'])->get('/centre-oversight')->assertOk();$this->get('/centre-oversight/apprentices/'.$f['a']->id.'/training')->assertOk()->assertSee('Record follow-up');$this->assertDatabaseCount('centre_manager_followups',0);$this->assertSame($before,DB::table('portal_operations_events')->count());}
 public function test_read_only_grant_shows_no_followup_creation_controls():void {$f=$this->f();$this->granted($f,['training']);$this->actingAs($f['manager'])->get('/centre-oversight/apprentices/'.$f['a']->id.'/training')->assertOk()->assertDontSee('Record follow-up')->assertSee('Creating a follow-up needs');}
 public function test_expired_or_revoked_grant_blocks_direct_urls():void {$f=$this->f();$g=$this->granted($f);A::revoke($f['admin'],1,$f['manager'],$g->version,'Fictional scope revoked');$this->actingAs($f['manager'])->get('/centre-oversight')->assertForbidden();$this->get('/centre-oversight/apprentices/'.$f['a']->id.'/training')->assertForbidden();}
 public function test_unsupported_or_overlong_attendance_period_is_refused():void {$f=$this->f();$this->granted($f);$this->reject(fn()=>O::position($f['manager'],$f['a'],'training','2025-01-01',today()->toDateString()));$this->actingAs($f['manager'])->get('/centre-oversight/apprentices/'.$f['a']->id.'/private_support')->assertNotFound();}
 public function test_existing_main_tutor_can_check_own_operational_source_without_new_grant():void {$f=$this->f();$p=O::position($f['tutor'],$f['a'],'training',$f['from'],$f['to']);$this->assertSame(1,$p['data']['overdue_work']);$this->assertFalse(A::workspace($f['tutor']));}
 public function test_string_roster_is_not_silently_treated_as_zero_recorded_otj():void {$f=$this->f();$this->granted($f,['attendance']);TrainingSession::factory()->create(['tutor_group_id'=>$f['group']->id,'created_by'=>$f['admin']->id,'session_date'=>today()->subDays(10),'members'=>[(string)$f['a']->id]]);$p=O::position($f['manager'],$f['a'],'attendance',$f['from'],$f['to']);$this->assertArrayHasKey('source_check',$p['data']['otj']);$this->assertArrayNotHasKey('recorded_minutes',$p['data']['otj']);$this->assertArrayHasKey('otj_source',$p['flags']);}
 public function test_missing_deadline_or_future_submission_is_an_explicit_source_check():void {$f=$this->f();$this->granted($f);$f['task']->forceFill(['due_date'=>null])->save();LearningTask::factory()->create(['apprentice_id'=>$f['a']->id,'reference'=>'FUTURE-SUBMISSION49','status'=>'Awaiting marking','submitted_at'=>now()->addDay(),'template'=>['kind'=>'task']]);$p=O::position($f['manager'],$f['a'],'training',$f['from'],$f['to']);$this->assertSame(2,$p['data']['source_checks']);$this->assertSame(0,$p['data']['marking_overdue']);$this->assertArrayHasKey('training_source',$p['flags']);}
}
